"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[1801],{1801(e,n,i){i.d(n,{content:()=>h,description:()=>s,keywords:()=>a,title:()=>t});i(5043);var r=i(579);const t="Wenn KI 'mindestens eins' falsch liest: Textbewertung scheitert",s="Ein Sch\xfcler aus Connecticut verlor Punkte, weil die KI 'mindestens eins' als 'nur eins' interpretierte. \xdcber 150 Sch\xfcler unterzeichneten eine Petition gegen KI-Bewertung. Deshalb eliminiert die Messung physischer Handlungen dieses Problem vollst\xe4ndig.",a=["KI-Bewertungsprobleme","prozessbasierte Bewertung","virtuelles Labor Bewertung","KI-Bewertungsfehler","automatisierte Aufsatzbewertung","virtuelles Labor","KI-Textinterpretation","Bildungstechnologie"],h=(0,r.jsxs)("div",{children:[(0,r.jsx)("p",{children:'Liam Roselle, ein Abiturient an der Amity Regional High School in Connecticut, erhielt eine Eins von drei Punkten bei zwei Fragen f\xfcr eine AP-Psychologie-Aufgabe. Das Feedback teilte ihm mit, dass er keine spezifischen Belege geliefert habe. Das hatte er aber. Das Problem, wie er schlie\xdflich herausfand, war, dass die Frage nach "mindestens einem konkreten und relevanten Beleg" fragte, und er hatte mehrere Studien zitiert. Das KI-Bewertungssystem interpretierte "mindestens eins" als "nur eins" und bestrafte ihn daf\xfcr, mehr als das Minimum geleistet zu haben.'}),(0,r.jsxs)("p",{children:['Um einen einzelnen Punkt bei einer Hausaufgabe zur\xfcckzugewinnen, musste Roselle eine dreiseitige E-Mail-Beschwerde schreiben, in der er den genauen Wortlaut der Frage zitierte und die Semantik des Ausdrucks "mindestens" erkl\xe4rte. Sein Lehrer stimmte zu, dass die Erkl\xe4rung Sinn ergab, und vergab den Punkt. Aber wie Roselle in'," ",(0,r.jsx)("a",{href:"https://ctmirror.org/2026/03/05/my-school-is-grading-me-with-ai-it-got-my-grade-wrong/",target:"_blank",rel:"noopener noreferrer",children:"CT Mirror"})," ",'schrieb: "Die Frage, die man stellen sollte, ist, wie viele Sch\xfcler, die mit dem gleichen Fehler konfrontiert waren, die Note einfach akzeptiert und weitergemacht haben."']}),(0,r.jsxs)("p",{children:["Er ist nicht allein mit seiner Sorge. Mehr als 150 Amity-Sch\xfcler haben eine Petition gegen KI-Bewertung an ihrer Schule unterzeichnet. Und ihre Bedenken werden durch Forschung gest\xfctzt: Eine Studie, die auf der Konferenz der American Educational Research Association 2024 pr\xe4sentiert wurde, ergab, dass"," ",(0,r.jsx)("a",{href:"https://hechingerreport.org/proof-points-ai-essay-grading/",target:"_blank",rel:"noopener noreferrer",children:"KI und menschliche Bewerter nur in etwa 40 Prozent der F\xe4lle exakt \xfcbereinstimmen"}),", mit einer konsistenten Voreingenommenheit gegen qualitativ hochwertige Texte. Wenn professionelle AP-Bewerter bei Aufs\xe4tzen unterschiedlicher Meinung sind, ziehen sie einen Mediator hinzu. KI-Bewertungssysteme bieten standardm\xe4\xdfig keine solche Absicherung."]}),(0,r.jsx)("h2",{children:"Warum hat KI Schwierigkeiten mit schriftlicher Bewertung?"}),(0,r.jsx)("p",{children:'Die Fehlinterpretation von "mindestens eins" ist kein Randfall. Sie offenbart eine grundlegende Einschr\xe4nkung der Art und Weise, wie KI-Systeme nat\xfcrliche Sprache verarbeiten. Diese Systeme arbeiten mit Mustererkennung: Sie lernen, wie "korrekte" Antworten typischerweise aussehen, und bewerten Einreichungen basierend auf der \xc4hnlichkeit zu diesen Mustern. Wenn ein Sch\xfcler korrektes Verst\xe4ndnis auf unerwartete Weise ausdr\xfcckt oder mehr als das erwartete Minimum liefert, erkennt das System es nicht.'}),(0,r.jsx)("p",{children:"Sprache ist von Natur aus mehrdeutig. Betrachten Sie, auf wie viele Arten ein Sch\xfcler dasselbe wissenschaftliche Konzept korrekt beschreiben k\xf6nnte:"}),(0,r.jsxs)("ul",{children:[(0,r.jsx)("li",{children:'"Die L\xf6sung wurde rosa" vs "Der Indikator ver\xe4nderte seine Farbe" vs "Eine Farbver\xe4nderung wurde beobachtet"'}),(0,r.jsx)("li",{children:'"Mindestens ein Beispiel" k\xf6nnte ein, zwei oder f\xfcnf Beispiele bedeuten'}),(0,r.jsx)("li",{children:'"Die Reaktion erfordert W\xe4rme" vs "thermische Energie wird ben\xf6tigt" vs "erh\xf6hte Temperatur"'}),(0,r.jsx)("li",{children:"Verschiedene Schreibweisen je nachdem, ob man britisches oder amerikanisches Englisch gelernt hat"})]}),(0,r.jsx)("p",{children:"Jede dieser Varianten dr\xfcckt dasselbe wissenschaftliche Verst\xe4ndnis aus. Ein menschlicher Bewerter erkennt sie als gleichwertig. Ein KI-System, das auf bestimmte Formulierungen trainiert wurde, m\xf6glicherweise nicht."}),(0,r.jsx)("p",{children:"Forschung zur automatisierten Aufsatzbewertung hat diese Fehler ausf\xfchrlich dokumentiert. KI-Systeme bestrafen unkonventionelle Satzstrukturen, selbst wenn der wissenschaftliche Inhalt korrekt ist. Sie belohnen weitschweifige, selbstbewusst klingende Prosa gegen\xfcber pr\xe4gnanten, genauen Antworten. Sie zeigen konsistente Voreingenommenheitsmuster, die bestimmte Schreibstile benachteiligen, unabh\xe4ngig vom demonstrierten Wissen."}),(0,r.jsx)("h2",{children:"Die versteckten Kosten von KI-Bewertungsfehlern"}),(0,r.jsx)("p",{children:"Roselles Fall veranschaulicht die versteckte Belastung, die KI-Bewertung den Sch\xfclern auferlegt. Er hat seine Note erfolgreich angefochten, aber daf\xfcr brauchte er akademische Schreibf\xe4higkeiten, Selbstvertrauen, um ein automatisiertes System herauszufordern, und einen Lehrer, der bereit war, die Beschwerde zu pr\xfcfen. Wie viele Sch\xfcler fehlt eines oder mehrere davon?"}),(0,r.jsx)("p",{children:"Die Sch\xfcler, die am ehesten eine falsche KI-Bewertung akzeptieren, sind oft diejenigen, die bereits akademisch k\xe4mpfen. Ihnen fehlt m\xf6glicherweise das Selbstvertrauen, Autorit\xe4t herauszufordern, selbst algorithmische Autorit\xe4t. Sie haben m\xf6glicherweise nicht die Schreibf\xe4higkeiten, um eine \xfcberzeugende Beschwerde zu verfassen. Sie haben vielleicht aus Erfahrung gelernt, dass ihre Einw\xe4nde abgewiesen werden. KI-Bewertungssysteme, die als objektiv und effizient pr\xe4sentiert werden, k\xf6nnen systematisch genau die Sch\xfcler benachteiligen, die die meiste Unterst\xfctzung brauchen."}),(0,r.jsx)("p",{children:"Dar\xfcber hinaus ergab Roselles FOIA-Anfrage, dass Amity Regional f\xfcnf KI-Produkte f\xfcr insgesamt 19.216,51 Dollar gekauft hatte, \xfcber 8.000 Dollar mehr als die 11.000-Dollar-Zahl, die der Bezirk \xf6ffentlich zitiert hatte. Die Diskrepanz wirft Fragen zur Transparenz und Rechenschaftspflicht bei der Beschaffung von Bildungstechnologie auf. Wenn Bezirke nicht genau berichten k\xf6nnen, welche KI-Tools sie verwenden und zu welchen Kosten, wird eine sinnvolle Aufsicht unm\xf6glich."}),(0,r.jsx)("h2",{children:"Was, wenn wir die Mehrdeutigkeit vollst\xe4ndig beseitigen w\xfcrden?"}),(0,r.jsx)("p",{children:"Es gibt eine Alternative dazu, KI-Systeme zu zwingen, mehrdeutigen Text zu interpretieren: Handlungen statt Worte bewerten. Wenn ein Sch\xfcler eine Titration in einem virtuellen Labor durchf\xfchrt, gibt es keine Mehrdeutigkeit dar\xfcber, ob er das Reagenz tropfenweise in der N\xe4he des Endpunkts hinzugef\xfcgt hat. Entweder hat er es getan oder nicht. Das System muss seine Beschreibung nicht analysieren; es beobachtet seine Technik direkt."}),(0,r.jsx)("p",{children:"Dies ist das Prinzip hinter der prozessbasierten Bewertung. Anstatt Sch\xfcler zu bitten zu beschreiben, was sie tun w\xfcrden, und dann ihre Sprache zu analysieren, beobachten Sie, was sie tats\xe4chlich tun, und messen es. Der Unterschied ist tiefgreifend:"}),(0,r.jsxs)("ul",{children:[(0,r.jsxs)("li",{children:[(0,r.jsx)("strong",{children:"Textbasiert:"}),' "Ich habe 2,5 Milliliter der L\xf6sung pipettiert" muss interpretiert werden. Meinten sie genau 2,5? Ungef\xe4hr 2,5? Beschrieben sie die durchgef\xfchrte Handlung oder die beabsichtigte Handlung?']}),(0,r.jsxs)("li",{children:[(0,r.jsx)("strong",{children:"Prozessbasiert:"})," Die virtuelle Pipette hat 2,47 ml \xfcbertragen aufgezeichnet. Keine Interpretation erforderlich."]})]}),(0,r.jsxs)("p",{children:["Das"," ",(0,r.jsx)("a",{href:"https://www.dreamscapelearn.com/research",target:"_blank",rel:"noopener noreferrer",children:"Dreamscape Learn-Programm"})," ","der Arizona State University demonstriert diesen Ansatz im gro\xdfen Ma\xdfstab. Sch\xfcler l\xf6sen biologische Probleme in immersiven VR-Umgebungen, und das System bewertet sie nach ihrem Denkweg durch das Problem, nicht nach schriftlichen Erkl\xe4rungen dessen, was sie getan haben. Erste Ergebnisse zeigen, dass Sch\xfcler in diesen prozessbasierten Abschnitten bessere Noten und eine bessere Retention erzielen als Mitsch\xfcler in konventionellen Kursen."]}),(0,r.jsx)("h2",{children:"Physik hat keine semantische Mehrdeutigkeit"}),(0,r.jsx)("p",{children:"Der grundlegende Vorteil der prozessbasierten Bewertung ist, dass physische Handlungen definitiv sind. Wenn ein Sch\xfcler einen Becher neigt, ist der Neigungswinkel messbar. Wenn er W\xe4rme anwendet, folgt die Temperatur\xe4nderung vorhersagbarer Physik. Wenn er das Volumen misst, hat die Messung einen spezifischen Wert. Es gibt keine Synonyme f\xfcr physische Handlungen."}),(0,r.jsx)("p",{children:"Deshalb haben wir WhimsyLabs um eine propriet\xe4re Physik-Engine herum gebaut, anstatt auf geskriptete Animationen zu setzen. Unsere Simulationen verfolgen tats\xe4chliche physikalische Gr\xf6\xdfen: das Volumen der Fl\xfcssigkeit in einem Beh\xe4lter, das genaue Timing von Zugaben, die Stetigkeit der Technik. Wenn wir die Leistung der Sch\xfcler bewerten, vergleichen wir ihre Handlungen mit korrekter Technik, nicht ihre Beschreibungen mit erwarteten Phrasen."}),(0,r.jsx)("p",{children:"Ein Sch\xfcler aus Deutschland, Japan oder Spanien f\xfchrt dieselbe Pipettierbewegung aus. Ein Sch\xfcler, der Englisch als Zweitsprache spricht, demonstriert dasselbe Verst\xe4ndnis, indem er einen Kolben im richtigen Moment schwenkt. Die universelle Sprache wissenschaftlicher Verfahren \xfcberwindet die Mehrdeutigkeiten, die textbasierte KI-Bewertung plagen."}),(0,r.jsx)("h2",{children:"Was ist mit schriftlichen Kommunikationsf\xe4higkeiten?"}),(0,r.jsx)("p",{children:"Eine berechtigte Frage stellt sich: Sollte naturwissenschaftliche Bildung nicht auch schriftliche Kommunikationsf\xe4higkeiten entwickeln? Die F\xe4higkeit, wissenschaftliche Verfahren klar zu beschreiben, ist wertvoll."}),(0,r.jsx)("p",{children:"Die Antwort ist ja, aber mit einer wichtigen Unterscheidung. Schriftliche Kommunikation ist eine F\xe4higkeit, die es wert ist, entwickelt zu werden, und sie kann bewertet werden, wenn das das explizite Ziel ist. Das Problem mit KI-bewerteten schriftlichen Pr\xfcfungen ist, dass sie wissenschaftliches Verst\xe4ndnis mit Schreibf\xe4higkeit verwechseln. Ein Sch\xfcler, der Titration tief versteht, aber unbeholfen schreibt, wird nicht f\xfcr wissenschaftliche Missverst\xe4ndnisse bestraft, sondern f\xfcr sprachliche. Ein Sch\xfcler, der fl\xfcssig schreibt, aber oberfl\xe4chlich versteht, kann h\xf6here Punkte erhalten."}),(0,r.jsx)("p",{children:"Prozessbasierte Bewertung trennt diese Anliegen. Wenn Sie wissenschaftliche Technik bewerten wollen, bewerten Sie die Technik direkt. Wenn Sie wissenschaftliche Kommunikation bewerten wollen, bewerten Sie die Kommunikation explizit. Geben Sie nicht vor, das eine zu messen, w\xe4hrend Sie tats\xe4chlich das andere messen."}),(0,r.jsx)("h2",{children:"Das wahre Versprechen von KI in der Bewertung"}),(0,r.jsx)("p",{children:"Die Fehler der KI-Textbewertung bedeuten nicht, dass KI keine Rolle bei der Bildungsbewertung hat. Sie bedeuten, dass KI auf Aufgaben angewendet werden sollte, bei denen sie hervorragend ist, anstatt auf Aufgaben, bei denen sie k\xe4mpft."}),(0,r.jsx)("p",{children:"KI ist hervorragend bei der Mustererkennung in strukturierten Daten, beim Verfolgen von Verfahrenssequenzen, beim Identifizieren spezifischer Technikfehler und beim Analysieren gro\xdfer Datens\xe4tze auf Muster. Diese F\xe4higkeiten sind perfekt f\xfcr prozessbasierte Bewertung geeignet, wo die Daten eindeutig sind und die Muster gut definiert."}),(0,r.jsx)("p",{children:"In WhimsyLabs verwendet unser KI-Tutor WhimsyCat Prozessdaten, um Echtzeit-Feedback zu geben. Wenn ein Sch\xfcler durch ein Verfahren hastet, bemerkt WhimsyCat es und schl\xe4gt vor, langsamer zu werden. Wenn ein Sch\xfcler denselben Fehler mehrmals wiederholt, erkl\xe4rt WhimsyCat, warum der Ansatz nicht funktioniert, und bietet Alternativen an. Dieses Feedback ist m\xf6glich, weil die Daten pr\xe4zise sind. WhimsyCat versucht nicht zu erraten, ob ein Sch\xfcler etwas aus einer mehrdeutigen Phrase verstanden hat; es hat genau beobachtet, was der Sch\xfcler getan hat."}),(0,r.jsx)("h2",{children:"Was Roselles Beschwerde offenbart"}),(0,r.jsx)("p",{children:'Zur\xfcck zu Liam Roselles Fall. Seine erfolgreiche Beschwerde erforderte von ihm zu erkl\xe4ren, mit Zitaten zum genauen Wortlaut der Frage, warum die Interpretation der KI falsch war. Sein Lehrer bemerkte, dass "da sowohl KI-Bewertungstools als auch Menschen Fragen und Antworten unterschiedlich interpretieren k\xf6nnen und fehlbar sind", er froh war, dass sie die Gelegenheit hatten, dar\xfcber zu diskutieren.'}),(0,r.jsx)("p",{children:"Diese Aussage offenbart unbeabsichtigt das Kernproblem. Wenn die Bewertung eine Interpretation von Sprache erfordert, ist Uneinigkeit unvermeidlich. Menschen sind sich untereinander uneinig. KI ist sich mit Menschen uneinig. KI ist sich mit sich selbst uneinig, wenn sie mit umformulierten Versionen identischer Inhalte konfrontiert wird. Das System ist instabil, weil Sprache instabil ist."}),(0,r.jsx)("p",{children:"Aber eine Pipettiertechnik erfordert keine Interpretation. Ein Titrationsendpunkt erfordert keine Interpretation. Der Winkel eines Bechers, das Timing einer Zugabe, die Stetigkeit einer Hand: Das sind Fakten, keine Interpretationen. Bewertung, die auf Fakten statt auf Interpretationen aufgebaut ist, liefert konsistente, verteidigbare Ergebnisse, die keine Beschwerden erfordern."}),(0,r.jsx)("h2",{children:"Der Weg nach vorn"}),(0,r.jsx)("p",{children:"Der Vorstand der Amity Regional High School sollte am 9. M\xe4rz 2026 \xfcber das Budget des n\xe4chsten Jahres abstimmen. Roselle hatte ihnen \xfcber zwei Wochen lang t\xe4glich E-Mails geschickt und sie gebeten, ernsthaft dar\xfcber nachzudenken, was 150 Sch\xfcler sagten und was ein Sch\xfcler tun musste, um einen Punkt zur\xfcckzugewinnen, den er bereits verdient hatte."}),(0,r.jsx)("p",{children:"Seine Situation spiegelt eine breitere Herausforderung wider, vor der die Bildung steht: der Druck, KI wegen Effizienzgewinnen einzuf\xfchren, ohne angemessen zu ber\xfccksichtigen, wo KI tats\xe4chlich gut funktioniert. Textinterpretation ist schwierig, weil Text mehrdeutig ist. Das ist keine vor\xfcbergehende Einschr\xe4nkung, die auf einen Durchbruch wartet. Es ist eine grundlegende Eigenschaft nat\xfcrlicher Sprache."}),(0,r.jsx)("p",{children:"Die L\xf6sung ist nicht, KI aufzugeben, sondern sie angemessen einzusetzen. Prozessbasierte Bewertung in virtuellen Laboren stellt einen solchen angemessenen Einsatz dar. Wenn Sch\xfcler ihr Verst\xe4ndnis durch Handlung statt durch Beschreibung demonstrieren, kann KI sie genau, fair und in gro\xdfem Ma\xdfstab bewerten. Die semantische Mehrdeutigkeit, die Roselle gefangen hielt, verschwindet vollst\xe4ndig."}),(0,r.jsx)("p",{children:"KI kann eine Pipettiertechnik nicht falsch lesen, weil es nichts falsch zu lesen gibt. Die Handlung ist entweder korrekt passiert oder nicht. In dieser Klarheit liegt eine bessere Zukunft f\xfcr die Bildungsbewertung."}),(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("h2",{children:"Verwandte Artikel"}),(0,r.jsxs)("ul",{children:[(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/ai-assessment-crisis-solution",children:"KI und die Bewertungskrise: Wie Prozessdaten alles ver\xe4ndern"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/edtech-critics-right-passive-learning-vs-active-labs",children:"Die Kritiker haben Recht: Die meiste EdTech ist nutzlos"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/vr-stem-education-research-pedagogical-scaffolding",children:"Neue VR-Forschung best\xe4tigt: Technologie ohne P\xe4dagogik scheitert"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/whimsycat-ai-tutor-transforming-science-education",children:"Lernen Sie WhimsyCat kennen: Unsere KI-Innovation in der naturwissenschaftlichen Bildung"})})]})]}),(0,r.jsxs)("div",{className:"references-section",children:[(0,r.jsx)("h3",{children:"Referenzen"}),(0,r.jsxs)("ul",{className:"references-list",children:[(0,r.jsxs)("li",{children:["Roselle, L. (2026, 5. M\xe4rz). My school is grading me with AI. It got my grade wrong."," ",(0,r.jsx)("em",{children:"CT Mirror"}),"."," ",(0,r.jsx)("a",{href:"https://ctmirror.org/2026/03/05/my-school-is-grading-me-with-ai-it-got-my-grade-wrong/",target:"_blank",rel:"noopener noreferrer",children:"https://ctmirror.org/2026/03/05/my-school-is-grading-me-with-ai-it-got-my-grade-wrong/"})]},"ref-1"),(0,r.jsxs)("li",{children:["Barshay, J. (2024). AI essay grading: What the research shows."," ",(0,r.jsx)("em",{children:"The Hechinger Report"}),"."," ",(0,r.jsx)("a",{href:"https://hechingerreport.org/proof-points-ai-essay-grading/",target:"_blank",rel:"noopener noreferrer",children:"https://hechingerreport.org/proof-points-ai-essay-grading/"})]},"ref-2"),(0,r.jsxs)("li",{children:["Dreamscape Learn. (2024). Research and outcomes at Arizona State University."," ",(0,r.jsx)("a",{href:"https://www.dreamscapelearn.com/research",target:"_blank",rel:"noopener noreferrer",children:"https://www.dreamscapelearn.com/research"})]},"ref-3"),(0,r.jsxs)("li",{children:["Keep Amity Human. (2026). FOIA documents on AI tools in Amity Regional School District."," ",(0,r.jsx)("a",{href:"https://keepamityhuman.org/foia.html",target:"_blank",rel:"noopener noreferrer",children:"https://keepamityhuman.org/foia.html"})]},"ref-4"),(0,r.jsx)("li",{children:"American Educational Research Association. (2024). Research on automated essay scoring reliability and bias."},"ref-5")]})]})]})}}]);
